          '抗鏈球菌溶血素抗體可顯示近期鏈球菌感染，用於特定情況，例如風濕熱的檢查。它不能用來決定每次喉嚨痛是否使用抗生素，沒有指示就檢驗反而造成混淆。 若結果不會改變處理方式，檢查可以省略，以減少費用與不適。',
          '懷疑合併症時會加做尿液與腎功能檢查。青少年淋巴結明顯腫大、肝脾可觸及時，檢驗 EB 病毒有助於排除單核球增多症。 淋巴結明顯壓痛與極度疲倦，也會引導檢查其他原因。',
