          '陰性結果不代表沒有疼痛、也不需要照護，只表示細菌性病因的可能性較低。是否重複檢驗或依臨床表現治療，由醫療人員決定。幼兒通常需要更謹慎。 家庭或學校出現群聚時，確認病原對於安排接觸者與減少新病例有幫助。',
