          '主動或被動吸菸都會刺激喉嚨，增加扁桃腺感染的機會。空調也會讓黏膜乾燥、降低局部抵抗力，尤其當設備沒有定期清潔時。 窗簾、地毯與抱枕會累積灰塵與菸霧，定期清潔對反覆發作的人有幫助。 有菸味的環境應由全家人共同避免，不只限於反覆發作的人。 清潔濾網與出風口，能避免設備把灰塵吹散。',
