          '一年反覆多次扁桃腺炎的人，值得檢查維持發炎的因素，例如胃食道逆流與長期暴露於菸霧。不處理這些因素，即使抗生素正確，發作仍會回來。 逆流可能沒有明顯症狀，卻在夜間刺激喉嚨，因此值得檢查。 逆流獲得治療後，夜間刺激減少，喉嚨發作也會變少。',
          '治療感冒與過敏性疾病，例如鼻炎，有助於減少因喉嚨痛就醫的次數。鼻炎會讓分泌物倒流，造成持續清喉嚨與刺激。 過敏原因獲得控制後，抗生素與症狀藥物的使用通常會下降。',
          '切除扁桃腺只在特定情況才建議，例如發作非常頻繁或出現合併症。即使切除，咽喉炎與喉炎仍可能發生，因為其他結構也會發炎。 手術決定會考量發作頻率、對呼吸的影響與合併症病史。 討論手術時應包含風險、好處與術後的改變。',
