          '從感染到出現第一個症狀的時間，取決於病原體與進入體內的數量。吃了同樣東西的兩個人可能在不同時間發病，其中一人甚至不會生病。因此，不一定找得出是哪一餐造成的，而急著追究那一餐對當下的照護幫助不大。',
          '最初幾小時，最有用的是觀察病程的節奏。當排便間隔拉長、嘔吐減少，通常會自行好轉。若情況相反，上廁所越來越密集或嘔吐不停，就應就醫而不是繼續等待。',
