          '安全的做法是先請基層健康中心轉介有評估的計畫。失代償期間、心律不整未控制與嚴重瓣膜疾病時不宜運動。即使在受監督的計畫中，出現胸痛、頭暈或與動作不成比例的喘時，也應立即停止。',
          '從未運動的人應從短而頻繁的步行開始，依耐受度逐漸增加，並全程接受指導。有人陪同、避開炎熱時段，比較容易維持習慣。目標不是運動表現，而是維持自理能力、減少日常活動中的喘。',
