        url: 'https://www.msdmanuals.com/pt/casa/dist%C3%BArbios-do-cora%C3%A7%C3%A3o-e-dos-vasos-sangu%C3%ADneos/arritmias-card%C3%ADacas/fibrila%C3%A7%C3%A3o-atrial-e-flutter-atrial',
        label: '心房顫動與心房撲動，健康科普版',
        publisher: 'MSD 診療手冊',
