          '不要徒手接觸鼠類或其巢穴。也不要在弄濕環境前，用工具、掃把或氣流揚起粉塵。在倉庫與儲藏室，濕式清潔與事前通風仍是防護的核心。',
          '在林地工作的田野人員與研究人員，應把暴露視為工作的一部分；之後若出現發燒或呼吸道症狀，應主動告知醫療人員。在雜物、木柴或農作物殘渣附近露營的人，也適用同樣原則。',
