          '絛蟲也可能因吃下蟲卵而感染。這種情況下，進入人體的是幼蟲，而不是腸道內的絛蟲成蟲。這項差異很重要：腦部與眼部形成囊腫的囊尾幼蟲病由此而來，而絛蟲病則來自吃下肉裡的囊尾幼蟲。',
          '蟲卵肉眼看不到，快速沖洗也不保證能去除。處理過的水、洗手，以及仔細清洗蔬菜與水果，能降低吃下蟲卵的機會。保持指甲剪短也有幫助，兒童尤其如此。',
