          '血吸蟲的尾動幼蟲在淡水中穿入皮膚。血吸蟲病流行區的河流、溪水、池塘與水庫都是接觸點。即使不喝水，只要進入水中，幼蟲就能穿過皮膚。',
          '這條途徑說明了為何穿鞋與行為和衛生設施同樣重要。在流行區避開河流與溪水、在受汙染的土壤上穿鞋，都是在蠕蟲進入人體之前就打斷生活史的措施。',
