          '絲蟲由蚊子傳播，不經土壤或水接觸。班氏吳策線蟲引起淋巴絲蟲病，表現為腿部持續腫脹。控制蚊子是這個生活史的核心措施，因為沒有病媒，幼蟲就到不了下一個人。',
          '把途徑分清楚很重要，因為它們需要不同的防護。穿鞋防的是土壤中的幼蟲，煮熟肉類阻斷絛蟲病，病媒控制則限制絲蟲病。單一措施無法涵蓋所有蠕蟲感染，但多項措施並用能讓社區的病例持續下降。',
