          '若症狀超過四週、疲倦影響日常生活，或出現心悸、胸痛、記憶與睡眠改變，建議回到醫療院所。這些不適可能屬於所謂的新冠長期症狀。',
          '從事面對人群工作，或照顧長者的人，恢復期要更謹慎：最初幾天仍戴口罩，避免與高風險者近距離接觸。能否復工依醫療院所評估與公司規定辦理。',
