          '排尿開始或結束時費力、尿流變細、夜裡頻繁起床，在 50 歲以上男性常是良性原因，但出現或加重時仍應就診。',
          '下背、髖部或肋骨持續疼痛，不明原因的體重下降，以及腿部水腫，都是晚期疾病的訊號，需要立即評估。到了這個階段，症狀已經來得太晚。',
