          '2024 年有 17.826 人因此死亡。調整後的發生率以東南、中西部與東北部較高，北部與南部較低，反映的是可近性與風險組成的差異。',
          '這些數字與保守的篩檢立場並存，原因在腫瘤的行為：大多數生長緩慢，真正的挑戰是把需要盡快治療的人，與可以追蹤的人分開。',
