          '減少紅肉與動物性脂肪、增加蔬菜，是飲食型態的改變，而不是短期節食。效果在數年間顯現，不會在下週就出現。',
          '任何年齡戒菸都值得。即使已吸菸數十年，也不是放棄的理由：吸菸者死於攝護腺癌的機會較高，而戒菸是離開這個族群的唯一方法。',
