          '當腫瘤已穿過胃壁或侵犯淋巴結，化學治療可能安排在手術之前。目的是縮小病灶、處理已經離開原位的細胞，讓手術更有機會切到乾淨的邊緣。並不是每個病例都走這條路，是否適合取決於分期。',
          '療程通常由數個週期組成，中間以影像檢查重新評估。腫瘤有反應，手術就接著進行。若治療期間疾病仍在進展，路線就要重新討論，有時開刀不再是第一順位的目標。',
          '這段時間需要照顧身體。化療期間體重與體力下降，會降低對治療與手術的耐受度，因此營養從一開始就納入照護，重點在蛋白質，必要時加上口服補充品。',
