          '什麼時候開始，取決於恢復狀況。病人要能吃、傷口在癒合、抵抗力還過得去，才適合接受療程；出現手術併發症時延後第一次治療很常見。這不是團隊疏忽，而是優先順序。',
          '這個階段的追蹤包括每個週期前的抽血、必要時調整劑量，以及症狀控制。把兩次治療之間的發燒、嘔吐、腹瀉與疲倦記錄下來，能幫團隊在不犧牲療效的前提下調整處方。需要調降劑量時，這不是疏忽，而是把療程調整到這個身體能承受的範圍。',
