          '這不代表治療沒有意義，也不代表無論如何都該做。誠實討論預期能換到什麼、要花多少時間在門診、哪些副作用可以接受，本身就是決定的一部分，而且每個階段都可以重新檢視。隨著每次反應重新檢視計畫，是照護的一部分，而不是團隊無故改變主意。',
          '當腫瘤出血或堵住胃的出口，會加上支持性處置，例如以內視鏡止血、放置支架或做繞道手術。症狀的緩解是實實在在的治療，不是照護裡較次要的一環。',
