          '在晚期疾病，免疫檢查點抑制劑已成為選項之一。是否適用取決於腫瘤的特性與先前嘗試過的治療，並不是所有病人都適合。',
          '多數情況下，這些藥物不是取代化療，而是加在化療之上。它們也不是憑偏好挑選：只有當腫瘤檢查顯示對應的標靶時才會使用，這也是切片與組織檢查如此重要的原因。',
