          '化療期間發燒不是在家觀察的症狀。抵抗力低時，普通的感染可能快速惡化，必須當天就醫，並讓服務單位知道病人正在接受治療。',
          '疲倦是預期中的，規律而溫和的活動，例如短程散步，會讓它好一些。睡眠、衛生與按時接種疫苗能保護抵抗力低的人，而家人的支持在治療沉重的日子裡格外重要。',
